function renderHome(){return header('index.html')+"\n<main class=\"climate-home\">\n<section class=\"section home-research editorial-topics\"><div class=\"wrap\"><div class=\"section-head\"><div><div class=\"eyebrow\">Explore the science</div><h2>Climate processes across<br>the Earth system.</h2></div><p></p></div><div class=\"home-research-grid\"><a class=\"home-research-card hc-mountain\" href=\"research.html#mountain-rainfall\"><span class=\"card-index\">01 / MOUNTAINS</span><span class=\"home-card-mark\">↗</span><span class=\"home-theme-icon\"><svg viewBox=\"0 0 64 64\" fill=\"none\" aria-hidden=\"true\"><path d=\"M4 49 23 17l12 20 8-12 17 24H4Z\" stroke=\"currentColor\" stroke-width=\"2.6\" stroke-linejoin=\"round\"/><path d=\"m15 31 8 6 6-10M5 55h54\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg></span><h3>Mountain climate<br>& precipitation</h3><p>Elevation-dependent warming, orography and snow cover.</p></a><a class=\"home-research-card hc-monsoon\" href=\"research.html#himalayan-monsoon\"><span class=\"card-index\">02 / ATMOSPHERE</span><span class=\"home-card-mark\">↗</span><span class=\"home-theme-icon\"><svg viewBox=\"0 0 64 64\" fill=\"none\" aria-hidden=\"true\"><path d=\"M9 18c5-6 13-6 18 0s13 6 18 0M7 30c8-7 18-7 26 0s16 7 24-1M9 43c5-6 13-6 18 0s13 6 18 0\" stroke=\"currentColor\" stroke-width=\"2.6\" stroke-linecap=\"round\"/></svg></span><h3>Monsoon &<br>circulation</h3><p>Moisture transport, low-level jets and rainfall variability.</p></a><a class=\"home-research-card hc-forest\" href=\"research.html#other-themes\"><span class=\"card-index\">03 / LAND</span><span class=\"home-card-mark\">↗</span><span class=\"home-theme-icon\"><svg viewBox=\"0 0 64 64\" fill=\"none\" aria-hidden=\"true\"><path d=\"M32 8c-12 9-18 17-18 27a18 18 0 0 0 36 0C50 25 44 17 32 8Z\" stroke=\"currentColor\" stroke-width=\"2.5\"/><path d=\"M32 20v35M32 34l-9-7M32 42l10-9\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"/></svg></span><h3>Land use &<br>hydroclimate</h3><p>Forest pathways, surface exchange and catchment hydrology.</p></a><a class=\"home-research-card hc-ocean\" href=\"research.html#arabian-sea\"><span class=\"card-index\">04 / OCEAN</span><span class=\"home-card-mark\">↗</span><span class=\"home-theme-icon\"><svg viewBox=\"0 0 64 64\" fill=\"none\" aria-hidden=\"true\"><path d=\"M6 22c6-6 12-6 18 0s12 6 18 0 12-6 16 0M6 34c6-6 12-6 18 0s12 6 18 0 12-6 16 0M6 46c6-6 12-6 18 0s12 6 18 0 12-6 16 0\" stroke=\"currentColor\" stroke-width=\"2.7\" stroke-linecap=\"round\"/></svg></span><h3>Ocean–atmosphere<br>interactions</h3><p>Air–sea coupling, ocean circulation and climate variability.</p></a><a class=\"home-research-card hc-polar\" href=\"research.html#other-themes\"><span class=\"card-index\">05 / POLAR</span><span class=\"home-card-mark\">↗</span><span class=\"home-theme-icon\"><svg viewBox=\"0 0 64 64\" fill=\"none\" aria-hidden=\"true\"><path d=\"M32 5v54M5 32h54M13 13l38 38M51 13 13 51\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"/></svg></span><h3>Polar amplification<br>& sea ice</h3><p>High-latitude warming and climate connections.</p></a></div><div class=\"topic-footer\"><span></span><a href=\"research.html\">View all research themes ↗</a></div></div></section>\n<section class=\"section editorial-latest\"><div class=\"wrap\"><div class=\"section-head\"><div><div class=\"eyebrow\">Research highlights</div><h2>Recent work & discoveries.</h2></div><a class=\"section-more\" href=\"publications.html\">All publications ↗</a></div><div class=\"latest-grid highlight-editorial-grid\"><a class=\"latest-paper highlight-tile highlight-tile-paleo\" href=\"https://doi.org/10.1029/2025PA005244\" target=\"_blank\" rel=\"noopener\"><div class=\"highlight-visual highlight-visual-paleo\" aria-hidden=\"true\"><span class=\"visual-kicker\">DEEP TIME · INDIAN OCEAN</span><div class=\"jet-lines\"><i></i><i></i><i></i><b></b></div><span class=\"visual-coordinate\">EOCENE / 3×CO₂</span></div><div class=\"highlight-content\"><div class=\"highlight-meta\"><span>01 / PALEOCLIMATE</span><span>2025</span></div><h3>Atmospheric Stabilization Weakened Proto-Low-Level Jet Over the Indian Ocean During the Eocene Hothouse</h3><p>How atmospheric circulation responded to the Eocene hothouse.</p><span class=\"highlight-read\">Read publication <b>↗</b></span></div></a><a class=\"latest-paper highlight-tile highlight-tile-hydro\" href=\"https://doi.org/10.5194/hess-29-4109-2025\" target=\"_blank\" rel=\"noopener\"><div class=\"highlight-visual highlight-visual-hydro\" aria-hidden=\"true\"><span class=\"visual-kicker\">TANA RIVER BASIN · EAST AFRICA</span><div class=\"river-lines\"><i></i><i></i><i></i><b></b></div><span class=\"visual-coordinate\">WRF-HYDRO / 5 KM</span></div><div class=\"highlight-content\"><div class=\"highlight-meta\"><span>02 / HYDROLOGICAL MODELLING</span><span>2025</span></div><h3>Enhanced hydrological modelling with the WRF-Hydro lake–reservoir module</h3><p>Representing lake and reservoir processes at convection-permitting scale.</p><span class=\"highlight-read\">Read publication <b>↗</b></span></div></a><a class=\"latest-paper highlight-tile highlight-tile-mountain\" href=\"https://doi.org/10.1029/2023EF003886\" target=\"_blank\" rel=\"noopener\"><div class=\"highlight-visual highlight-visual-mountain\" aria-hidden=\"true\"><span class=\"visual-kicker\">HIGH-MOUNTAIN ASIA</span><div class=\"mountain-lines\"><i></i><i></i><i></i><b></b></div><span class=\"visual-coordinate\">ELEVATION · PRECIPITATION</span></div><div class=\"highlight-content\"><div class=\"highlight-meta\"><span>03 / MOUNTAIN CLIMATE</span><span>2023</span></div><h3>Projected Changes in Mountain Precipitation Under CO₂-Induced Warmer Climate</h3><p>Precipitation responses across mountain regions in a warming climate.</p><span class=\"highlight-read\">Read publication <b>↗</b></span></div></a></div>\n<section class=\"section editorial-about\"><div class=\"wrap editorial-about-inner\"><div><div class=\"eyebrow\">About the researcher</div><h2>Pratik Kad</h2><p>Climate scientist working on mountain climate, hydroclimate, atmospheric circulation and climate dynamics. Research combines regional climate modelling, observations and physical analysis of climate processes.</p><a class=\"section-more\" href=\"about.html\">More about Pratik ↗</a></div><div class=\"editorial-about-links\"><a href=\"research.html\">Research themes <span>↗</span></a><a href=\"publications.html\">Peer-reviewed publications <span>↗</span></a><a href=\"outreach.html\">Articles, lectures & conferences <span>↗</span></a></div></div></section>\n</main>"+footer()}
